"""地图页面基类 — 声明共享依赖与公共查询方法。

所有面板 Mixin 均继承 :class:`BaseMapPage`，
最终由 :class:`~autowsgr.ui.map.page.MapPage` 组合为完整控制器。
"""

from __future__ import annotations

from typing import TYPE_CHECKING

from autowsgr.infra.exceptions import PageDriftError
from autowsgr.infra.logger import get_logger
from autowsgr.types import PageName
from autowsgr.ui.map.data import (
    CLICK_BACK,
    CLICK_EXPEDITION_SKIP,
    CLICK_PANEL,
    EXPEDITION_NOTIF_COLOR,
    EXPEDITION_NOTIF_PROBE,
    EXPEDITION_TOLERANCE,
    PANEL_LIST,
    PANEL_TO_INDEX,
    TITLE_CROP_REGION,
    MapIdentity,
    MapPanel,
    parse_map_title,
)
from autowsgr.ui.stack import record_page_substate
from autowsgr.ui.tabbed_page import (
    TabbedPageType,
    check_tabbed_page,
    get_active_tab_index,
    make_tab_checker,
)
from autowsgr.ui.utils import NavConfig, NavigationError, click_and_wait_for_page, wait_for_page
from autowsgr.vision import OCREngine, PageMatch, PixelChecker


if TYPE_CHECKING:
    import numpy as np

    from autowsgr.context import GameContext


_log = get_logger('ui')


class BaseMapPage:
    """地图页面基类。

    声明所有面板 Mixin 需要的共享依赖与公共查询 / 导航方法。

    Parameters
    ----------
    ctrl:
        Android 设备控制器实例。
    ocr:
        OCR 引擎实例 (可选，章节导航时需要)。
    """

    def __init__(
        self,
        ctx: GameContext,
    ) -> None:
        self._ctx = ctx
        self._ctrl = ctx.ctrl
        self._ocr = ctx.ocr

    # ═══════════════════════════════════════════════════════════════════════
    # 页面识别
    # ═══════════════════════════════════════════════════════════════════════

    @staticmethod
    def is_current_page(screen: np.ndarray) -> PageMatch:
        """判断截图是否为地图页面 (返回带覆盖度分数的 PageMatch)。"""
        return check_tabbed_page(screen, TabbedPageType.MAP)

    # ═══════════════════════════════════════════════════════════════════════
    # 状态查询 — 面板
    # ═══════════════════════════════════════════════════════════════════════

    @staticmethod
    def get_active_panel(screen: np.ndarray) -> MapPanel | None:
        """获取当前激活的面板标签。"""
        idx = get_active_tab_index(screen)
        if idx is None or idx >= len(PANEL_LIST):
            return None
        return PANEL_LIST[idx]

    # ═══════════════════════════════════════════════════════════════════════
    # 状态查询 — 远征通知
    # ═══════════════════════════════════════════════════════════════════════

    @staticmethod
    def has_expedition_notification(screen: np.ndarray) -> bool:
        """检测是否有远征完成通知。"""
        x, y = EXPEDITION_NOTIF_PROBE
        return PixelChecker.get_pixel(screen, x, y).near(
            EXPEDITION_NOTIF_COLOR, EXPEDITION_TOLERANCE
        )

    # ═══════════════════════════════════════════════════════════════════════
    # 状态查询 — 侧边栏 (章节位置)
    # ═══════════════════════════════════════════════════════════════════════

    DEFAULT_CHAPTER_Y: float = 0.556
    """侧边栏默认选中章节的 y 坐标（相对高度）。

    这是「章节列表停在默认位置时」的选中项位置常量，不是扫描结果。
    旧 API ``find_selected_chapter_y()`` 名字暗示会读取当前选中项，但实现
    从未截图/OCR，始终返回本值；7.3 改名为常量以保持名实一致。
    ``click_chapter`` 用它做相对跳转；若将来需要真实定位选中章节，
    应新增一个真正扫描屏幕、返回实际 y 的方法。
    """

    # ═══════════════════════════════════════════════════════════════════════
    # 状态查询 — 地图 OCR
    # ═══════════════════════════════════════════════════════════════════════

    @staticmethod
    def recognize_map(
        screen: np.ndarray,
        ocr: OCREngine,
    ) -> MapIdentity | None:
        """通过 OCR 识别当前地图。"""
        x1, y1, x2, y2 = TITLE_CROP_REGION
        cropped = PixelChecker.crop(screen, x1, y1, x2, y2)
        result = ocr.recognize_maxlen(cropped)
        if not result.text:
            _log.debug('[UI] 地图标题 OCR 无结果')
            return None

        info = parse_map_title(result.text)
        if info is None:
            _log.debug("[UI] 地图标题解析失败: '{}'", result.text)
        else:
            _log.debug(
                '[UI] 地图识别: 第{}章 {}-{} {}',
                info.chapter,
                info.chapter,
                info.map_num,
                info.name,
            )
        return info

    # ═══════════════════════════════════════════════════════════════════════
    # 动作 — 回退 / 面板切换 / 通用点击
    # ═══════════════════════════════════════════════════════════════════════

    def go_back(self) -> None:
        """点击回退按钮 (◁)，返回主页面。"""
        from autowsgr.ui.main_page import MainPage

        _log.info('[UI] 地图页面 → 回退')
        click_and_wait_for_page(
            self._ctrl,
            click_coord=CLICK_BACK,
            checker=MainPage.is_current_page,
            source=PageName.MAP,
            target=PageName.MAIN,
            stop_event=self._ctx.stop_event,
        )

    _PANEL_SWITCH_CONFIG = NavConfig(
        max_retries=3,
        retry_delay=0.5,
        timeout=4.0,
        interval=0.4,
        stable_frames=2,
    )
    """面板切换的闭环配置：最多 3 次点击，并要求连续两帧命中目标标签。"""

    def switch_panel(self, panel: MapPanel) -> None:
        """切换到指定面板标签，点击后必须识别到目标面板才算成功。"""
        current = self.get_active_panel(self._ctrl.screenshot())
        _log.info(
            '[UI] 地图页面: {} → {}',
            current.value if current else '未知',
            panel.value,
        )
        target_idx = PANEL_TO_INDEX[panel]
        source = f'地图-{current.value if current else "?"}'
        target = f'地图-{panel.value}'

        try:
            click_and_wait_for_page(
                self._ctrl,
                click_coord=CLICK_PANEL[panel],
                checker=make_tab_checker(TabbedPageType.MAP, target_idx),
                source=source,
                target=target,
                config=self._PANEL_SWITCH_CONFIG,
                stop_event=self._ctx.stop_event,
            )
        except NavigationError as exc:
            raise PageDriftError(
                f'地图面板切换失败: {source} -> {target}',
                target=target,
                page_trail=[source, target],
                action_trail=[f'click_panel({panel.value})'],
                screen=self._ctrl.screenshot(),
            ) from exc

    def ensure_panel(self, panel: MapPanel) -> None:
        """确保当前处于指定面板；点击后复核目标标签连续两帧命中。

        已是目标面板时不会重复点击，但仍做一次识别复核 —— 「确保」的语义
        是**确认**，不是「没点就假定成功」。
        """
        screen = self._ctrl.screenshot()
        current = self.get_active_panel(screen)
        source = f'地图-{current.value if current else "?"}'
        target = f'地图-{panel.value}'

        if current != panel:
            self.switch_panel(panel)

        try:
            wait_for_page(
                self._ctrl,
                checker=make_tab_checker(TabbedPageType.MAP, PANEL_TO_INDEX[panel]),
                timeout=1.5,
                interval=0.25,
                stable_frames=2,
                source=source,
                target=target,
                stop_event=self._ctx.stop_event,
            )
        except NavigationError as exc:
            raise PageDriftError(
                f'目标面板复核失败: {source} -> {target}',
                target=target,
                page_trail=[source, target],
                action_trail=[f'ensure_panel({panel.value})'],
                screen=self._ctrl.screenshot(),
            ) from exc

        record_page_substate(self._ctx, PageName.MAP, panel.value)

    def click_expedition_skip(self) -> None:
        """点击屏幕右侧 — 用于跳过远征动画。"""
        self._ctrl.click(*CLICK_EXPEDITION_SKIP)
